package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.nio.file.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RucesionServicesV156Test {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String key:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(key,0).edit().clear().commit();F5mSaveStore.install(c);}
 Object call(GameView v,String n,Class<?>[] types,Object...args)throws Exception{Method m=GameView.class.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(v,args);}
 GameView town()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);call(v,"enterPoteField",new Class<?>[]{});call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},RucesionTownGeometry.ID,false);return v;}
 void enter(GameView v,TownInteriorDef d)throws Exception{RuntimeState s=TownInteriorTest.field(v,"state");WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");RucesionTownGeometry.Building b=RucesionTownGeometry.forInterior(d.mapId);s.player().x=RucesionTownGeometry.x(b.prop.u,b.prop.v+2);s.player().y=RucesionTownGeometry.y(b.prop.u,b.prop.v+2);w.cancelForAction();w.snapCameraToPlayer();WorldCameraTransform.Point at=w.worldToScreen(b.doorX(),b.doorY());TownInteriorTest.tap(v,at.x,at.y);for(int i=0;i<180&&RucesionTownGeometry.ID.equals(s.currentMapId());i++)TownInteriorTest.tick(v,1);assertEquals(d.mapId,s.currentMapId());}
 void capture(GameView v,String n)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));java.nio.file.Path p=Paths.get("build/reports/town-v156/"+n+".png");Files.createDirectories(p.getParent());try(OutputStream out=Files.newOutputStream(p)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}b.recycle();}
 void merchant(GameView v,TownInteriorDef d)throws Exception{WorldRuntimeAdapter w=TownInteriorTest.field(v,"reagentShopAdapter");WorldCameraTransform.Point p=w.worldToScreen(d.npcX(),d.npcY());TownInteriorTest.tap(v,p.x,p.y-24);if(d.kind==TownInteriorDef.Kind.INN)TownInteriorTest.tick(v,400);else assertTrue(((TownShopWindow)TownInteriorTest.field(v,"townWindow")).isOpen());}
 void confirm(GameView v)throws Exception{TownInteriorDef d=TownInteriorTest.field(v,"townInterior");if(d.kind==TownInteriorDef.Kind.REAGENT||d.kind==TownInteriorDef.Kind.EQUIPMENT){TownInteriorTest.tap(v,761.25f,376.875f);TownInteriorTest.tap(v,671.25f,326.25f);}else{TownInteriorTest.tap(v,760,385);TownInteriorTest.tap(v,580,306);}}
 @Test public void sevenDoorsHaveReachableDistinctInteriorsAndNativeServiceWindows()throws Exception{
  assertEquals(7,TownInteriorDef.RUCESION.size());assertEquals(7,RucesionTownGeometry.BUILDINGS.size());
  Set<String> maps=new HashSet<>(),doors=new HashSet<>();for(TownInteriorDef d:TownInteriorDef.RUCESION){reset();GameView v=town();enter(v,d);assertTrue(maps.add(d.mapId));assertTrue(doors.add(d.doorId));RuntimeState s=TownInteriorTest.field(v,"state");assertTrue(s.monsters().isEmpty());WorldRuntimeAdapter w=TownInteriorTest.field(v,"reagentShopAdapter");assertTrue(d.mapId,CampaignNavigationTest.walk(w,w.requestGroundWorld(d.customerX(),d.customerY())));capture(v,d.doorId+"-room");merchant(v,d);capture(v,d.doorId+"-service");}
 }
 @Test public void weaponArmorAndSourceRucesionClothingUseDifferentInventoriesAndDurableNativePurchases()throws Exception{
  for(String id:new String[]{"rucesion_interior_weapon","rucesion_interior_armor","rucesion_interior_clothing","rucesion_interior_reagent"}){reset();GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreGold(100000);TownInteriorDef d=TownInteriorDef.forMap(id);List<TownCommerce.Offer> goods=TownCommerce.offers(d,s);assertFalse(id,goods.isEmpty());if(id.endsWith("weapon"))assertTrue(goods.stream().allMatch(o->o.category.equals("무기")));if(id.endsWith("armor"))assertTrue(goods.stream().noneMatch(o->o.category.equals("무기")));if(id.endsWith("clothing"))assertTrue(goods.stream().allMatch(o->o.name.startsWith("뤼케시온")&&s.rpg().itemDefinitions().get(o.id).equipSlot.equals("갑옷")));
   enter(v,d);merchant(v,d);TownCommerce.Offer first=goods.get(0);int old=s.rpg().inventory().getOrDefault(first.id,0);long gold=s.rpg().gold();TownInteriorTest.tap(v,423.75f,168.75f);confirm(v);assertEquals(old+1,s.rpg().inventory().get(first.id).intValue());assertEquals(gold-first.price,s.rpg().gold().longValue());capture(v,d.doorId+"-purchase");F5mSaveStore.install(c);GameView fresh=new GameView(c);fresh.layout(0,0,960,540);RuntimeState restored=TownInteriorTest.field(fresh,"state");assertEquals(d.mapId,restored.currentMapId());assertEquals(old+1,restored.rpg().inventory().get(first.id).intValue());assertEquals(gold-first.price,restored.rpg().gold().longValue());
   merchant(fresh,d);TownInteriorTest.tap(fresh,705,517.5f);TownInteriorTest.tap(fresh,513.75f,360);confirm(fresh);assertEquals(old,restored.rpg().inventory().getOrDefault(first.id,0).intValue());assertEquals(gold-first.price+first.price/2,restored.rpg().gold().longValue());capture(fresh,d.doorId+"-sale");
   if(id.endsWith("weapon"))assertEquals(TownCommerce.Result.INVALID,TownCommerce.transact(restored,d,TownCommerce.Operation.BUY,"IT_TEST_ARMOR_MU0000002",1,()->true));
  }
 }
 @Test public void bankNativeDepositRestoresAndBankBUsesTheSameDurableAccount()throws Exception{
  GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreGold(2000);TownInteriorDef a=TownInteriorDef.forMap("rucesion_interior_bank_a");enter(v,a);merchant(v,a);confirm(v);assertEquals(1999,s.rpg().gold().longValue());assertEquals(1,s.rpg().bankGold());capture(v,"bank-a-deposit");F5mSaveStore.install(c);GameView fresh=new GameView(c);fresh.layout(0,0,960,540);RuntimeState rs=TownInteriorTest.field(fresh,"state");assertEquals(1,rs.rpg().bankGold());call(fresh,"leaveReagentShop",new Class<?>[]{});TownInteriorDef b=TownInteriorDef.forMap("rucesion_interior_bank_b");enter(fresh,b);merchant(fresh,b);TownInteriorTest.tap(fresh,445,112);confirm(fresh);assertEquals(0,rs.rpg().bankGold());assertEquals(2000,rs.rpg().gold().longValue());capture(fresh,"bank-b-withdraw");
  assertEquals(TownCommerce.Result.SAVE_FAILED,TownCommerce.transact(rs,b,TownCommerce.Operation.DEPOSIT_GOLD,"GOLD",100,()->false));assertEquals(2000,rs.rpg().gold().longValue());assertEquals(0,rs.rpg().bankGold());
 }
 @Test public void bankItemDepositAndWithdrawalAreNativeAndShareRestartedStorage()throws Exception{
  GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");String item="IT_REAGENT_CURANUM";int initial=s.rpg().inventory().getOrDefault(item,0);assertEquals(RpgProgressionState.AutoLootResult.LOOTED,s.rpg().autoLootResolvedItem(item,2));TownInteriorDef a=TownInteriorDef.forMap("rucesion_interior_bank_a");enter(v,a);merchant(v,a);TownInteriorTest.tap(v,600,112);
  TownShopWindow window=TownInteriorTest.field(v,"townWindow");Method rows=TownShopWindow.class.getDeclaredMethod("rows");rows.setAccessible(true);List<TownCommerce.Offer> list=(List<TownCommerce.Offer>)rows.invoke(window);int index=-1;for(int i=0;i<list.size();i++)if(list.get(i).id.equals(item))index=i;assertTrue(index>=0);for(int i=0;i<index/4;i++)TownInteriorTest.tap(v,565,345);TownInteriorTest.tap(v,350,185+43*(index%4));confirm(v);assertEquals(initial+1,s.rpg().inventory().get(item).intValue());assertEquals(1,s.rpg().bankInventory().get(item).intValue());capture(v,"bank-a-item-deposit");F5mSaveStore.install(c);GameView fresh=new GameView(c);fresh.layout(0,0,960,540);RuntimeState rs=TownInteriorTest.field(fresh,"state");assertEquals(1,rs.rpg().bankInventory().get(item).intValue());call(fresh,"leaveReagentShop",new Class<?>[]{});TownInteriorDef b=TownInteriorDef.forMap("rucesion_interior_bank_b");enter(fresh,b);merchant(fresh,b);TownInteriorTest.tap(fresh,750,112);TownInteriorTest.tap(fresh,350,185);confirm(fresh);assertEquals(initial+2,rs.rpg().inventory().get(item).intValue());assertFalse(rs.rpg().bankInventory().containsKey(item));capture(fresh,"bank-b-item-withdrawal");
 }
 @Test public void rucesionInnRestUsesActualDialogueAndPreservesTownReturnAndSave()throws Exception{
  GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreGold(500);TownInteriorDef inn=TownInteriorDef.forMap("rucesion_interior_inn");enter(v,inn);merchant(v,inn);assertEquals(true,TownInteriorTest.field(v,"innDialogueOpen"));s.player().hp=1;s.player().mp=1;TownInteriorTest.tap(v,575,425);assertEquals(450,s.rpg().gold().longValue());assertEquals(s.player().maxHp,s.player().hp);assertEquals(s.player().maxMp,s.player().mp);capture(v,"inn-after-rest");assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView fresh=new GameView(c);fresh.layout(0,0,960,540);RuntimeState rs=TownInteriorTest.field(fresh,"state");assertEquals(450,rs.rpg().gold().longValue());call(fresh,"leaveReagentShop",new Class<?>[]{});assertEquals(RucesionTownGeometry.ID,rs.currentMapId());assertFalse(rs.blocked(rs.player().x,rs.player().y));
 }
}
